    ('00000000-2026-4000-8000-000000000002', NULL, 1, 5, 2, 'Saludos', 'Comprensión de expresiones cotidianas', 'Luis se va a casa después de clases. ¿Qué palabra puede decir al despedirse?', 'Luis se despide de sus amigos.', NULL, NULL, 'seleccion_unica', 1, 'Goodbye se usa para decir adiós.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000003', NULL, 1, 5, 2, 'Cortesía', 'Comprensión de expresiones cotidianas', '¿Qué palabra en inglés usamos para pedir algo con amabilidad?', 'Camila quiere pedir un lápiz prestado.', NULL, NULL, 'seleccion_unica', 1, 'Please significa por favor.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000004', NULL, 1, 5, 2, 'Cortesía', 'Interacción en situaciones cotidianas', 'Sara dice: “Thank you”. ¿Cuál es la respuesta más adecuada?', 'Sara agradece a Tomás por ayudarle.', NULL, NULL, 'seleccion_unica', 2, 'You''re welcome significa con gusto o de nada.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000005', NULL, 1, 5, 2, 'Información personal', 'Comprensión de preguntas personales sencillas', 'What is your name?', 'Escoge la respuesta que contesta la pregunta.', NULL, NULL, 'seleccion_unica', 1, 'My name is Laura responde cómo se llama una persona.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000006', NULL, 1, 5, 2, 'Información personal', 'Comprensión de preguntas personales sencillas', 'How old are you?', 'Mateo tiene ocho años. Escoge su respuesta.', NULL, NULL, 'seleccion_unica', 2, 'I am eight years old expresa que Mateo tiene ocho años.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000007', NULL, 1, 5, 2, 'Números del 1 al 20', 'Reconocimiento de vocabulario numérico', '¿Cómo se escribe el número 5 en inglés?', NULL, NULL, NULL, 'seleccion_unica', 1, 'El número 5 se escribe five.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000008', NULL, 1, 5, 2, 'Números del 1 al 20', 'Reconocimiento de secuencias numéricas', 'Complete the sequence: seven, eight, ____.', 'Completa la secuencia de números en inglés.', NULL, NULL, 'seleccion_unica', 2, 'Después de eight viene nine.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000009', NULL, 1, 5, 2, 'Números del 1 al 20', 'Reconocimiento de vocabulario numérico', '¿Qué número representa la palabra “twelve”?', NULL, NULL, NULL, 'seleccion_unica', 2, 'Twelve corresponde al número 12.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000010', NULL, 1, 5, 2, 'Números del 1 al 20', 'Reconocimiento de vocabulario numérico', '¿Cómo se escribe el número 20 en inglés?', NULL, NULL, NULL, 'seleccion_unica', 2, 'El número 20 se escribe twenty.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000011', NULL, 1, 5, 2, 'Números del 1 al 20', 'Comprensión de cantidades sencillas', 'There are three books. ¿Cuántos libros hay?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Three significa tres.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000012', NULL, 1, 5, 2, 'Números del 1 al 20', 'Comprensión de cantidades sencillas', 'Sofía has ten crayons and gives one away. How many crayons does she have now?', 'Sofía tiene diez colores y regala uno.', NULL, NULL, 'seleccion_unica', 3, 'Ten minus one is nine; nine significa nueve.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000013', NULL, 1, 5, 2, 'Colores', 'Asociación de palabras con características visibles', 'An apple is red. ¿De qué color es la manzana?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Red significa rojo.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000014', NULL, 1, 5, 2, 'Colores', 'Reconocimiento de vocabulario básico', '¿Cuál es la palabra en inglés para el color azul?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Azul en inglés es blue.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
