    ('00000000-2026-4000-8000-000000000016', NULL, 1, 5, 2, 'Formas', 'Reconocimiento de vocabulario básico', 'A ball is round. Which shape is it?', 'Una pelota tiene forma redonda.', NULL, NULL, 'seleccion_unica', 2, 'Una pelota se relaciona con la forma circle.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000017', NULL, 1, 5, 2, 'Formas', 'Reconocimiento de vocabulario básico', '¿Cuál figura tiene tres lados?', 'Escoge el nombre de la figura en inglés.', NULL, NULL, 'seleccion_unica', 2, 'Triangle significa triángulo, una figura de tres lados.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
    ('00000000-2026-4000-8000-000000000018', NULL, 1, 5, 2, 'Tamaños', 'Comprensión de adjetivos básicos', 'An elephant is big. ¿Qué significa “big”?', NULL, NULL, NULL, 'seleccion_unica', 1, 'Big significa grande.', 'propia', NULL, NULL, NULL, 'borrador', v_actor, v_actor, NULL),
